css:
@page {
    size: A4;
    margin: 0;
}
html, body {
    margin: 0;
    padding: 0;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
    font-family: Calibri, sans-serif;
}
/* Kill Frappe letter head completely */
.letter-head, #header-html, #footer-html, .letterhead { display: none !important; }
.print-format { padding: 0 !important; margin: 0 !important; }

.bvr-page {
    position: relative;
    width: 210mm;
    box-sizing: border-box;
    font-family: Calibri, sans-serif;
    font-size: 13px;
    color: #000;
}

/* Custom header: teal box with logo only — NO tagline strip */
.bvr-header {
    width: 100%;
    background-color: #00695c;
    padding: 10px 18px;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: 14px;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}
.bvr-header img.bvr-logo {
    height: 40px;
    width: auto;
}
.bvr-header .bvr-org-name {
    color: #fff;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: 1px;
    line-height: 1.1;
    font-family: Calibri, sans-serif;
}
.bvr-header .bvr-org-sub {
    color: #b2dfdb;
    font-size: 10px;
    letter-spacing: 0.5px;
    font-family: Calibri, sans-serif;
}

/* Footer strip */
.bvr-footer {
    width: 100%;
    background-color: #00695c;
    text-align: center;
    color: #fff;
    font-size: 10px;
    padding: 5px 18px;
    box-sizing: border-box;
    margin-top: 14px;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.bvr-content {
    padding: 5mm 18mm 0 18mm;
    box-sizing: border-box;
}

/* Watermark logo */
.bvr-watermark {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 120mm;
    opacity: 0.05;
    z-index: 0;
    pointer-events: none;
}
.bvr-body { position: relative; z-index: 1; }

.bvr-title {
    text-align: center;
    font-size: 15px;
    font-weight: bold;
    margin-bottom: 12px;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: #00695c;
    border-bottom: 2px solid #00695c;
    padding-bottom: 5px;
}
.bvr-meta-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px 20px;
    margin-bottom: 12px;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    background: #f9fafb;
    font-size: 12px;
}
.bvr-meta-row { display: flex; gap: 6px; }
.bvr-meta-label { font-weight: 700; color: #444; white-space: nowrap; }
.bvr-section-title {
    font-size: 12px;
    font-weight: 700;
    color: #00695c;
    background: #e8f5e9;
    border-left: 4px solid #00695c;
    padding: 4px 10px;
    margin: 12px 0 5px 0;
    border-radius: 0 4px 4px 0;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}
.bvr-responses-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    margin-bottom: 8px;
}
.bvr-responses-table th {
    background: #e0f2f1;
    color: #00695c;
    font-weight: 700;
    padding: 5px 8px;
    border: 1px solid #ccc;
    text-align: left;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}
.bvr-responses-table td {
    padding: 4px 8px;
    border: 1px solid #e0e0e0;
    vertical-align: top;
}
.bvr-responses-table tr:nth-child(even) td { background: #f9fafb; }
.bvr-summary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 8px;
}
.bvr-summary-box {
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 12px;
}
.bvr-summary-box ol { margin: 4px 0 0 0; padding-left: 18px; }
.bvr-summary-box ol li { margin-bottom: 3px; }
.bvr-signoff {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-top: 16px;
    padding-top: 12px;
    border-top: 1px solid #ccc;
    font-size: 12px;
}
.bvr-badge {
    display: inline-block;
    padding: 1px 8px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 700;
    background: #e0f2f1;
    color: #00695c;
    border: 1px solid #00695c;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}
.bvr-action-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
    margin-bottom: 8px;
}
.bvr-action-table th {
    background: #e0f2f1;
    color: #00695c;
    font-weight: 700;
    padding: 5px 8px;
    border: 1px solid #ccc;
    text-align: left;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}
.bvr-action-table td {
    padding: 4px 8px;
    border: 1px solid #e0e0e0;
    vertical-align: top;
}
.bvr-action-table tr:nth-child(even) td { background: #f9fafb; }
.bvr-responses-table td.bvr-cat-row {
    background: #e8f4f1;
    font-weight: 700;
    color: #1a7a6a;
    padding: 6px 8px;
}
.bvr-responses-table td {
    vertical-align: top;
}

/* --- keep content clear of the footer image + clean page breaks --- */
.bvr-responses-table thead,
.bvr-action-table thead {
    display: table-header-group;
}
.bvr-responses-table tr,
.bvr-action-table tr {
    page-break-inside: avoid;
    break-inside: avoid;
}
.bvr-responses-table,
.bvr-action-table {
    page-break-inside: auto;
    break-inside: auto;
}
.bvr-section-title {
    page-break-after: avoid;
    break-after: avoid;
}

.bvr-foot {
    position: relative;
    width: 210mm;
    height: 26mm;
    overflow: hidden;
    margin: 12px -18mm 0 -18mm;
}
.bvr-foot img {
    position: absolute;
    top: -271mm;
    left: 0;
    width: 210mm;
    height: 297mm;
}

/* Action Items + sign-off + footer always travel together: if less than about
   half a page is left, the whole block moves to the next page */
.bvr-action-block {
    break-inside: avoid;
    page-break-inside: avoid;
    min-height: 120mm;
}
